const TOUR = {"seoul":{"경복궁":["126508","경복궁","경복궁은 1392년 조선 건국 후 1395년(태조 4)에 창건한 조선왕조 제일의 법궁이다.","data:image/jpeg;base64,","1",126.97672,37.57603],"북촌한옥마을":["126537","북촌한옥마을","북촌은 경복궁과 창덕궁, 종묘 사이에 위치한 곳으로 전통한옥이 밀집되어 있는 서울의 대표적인 전통 주거지역이다.","","3",126.98669,37.579],"광장시장":["132183","광장시장","구한말 국내 정세가 혼미를 거듭하던 중 일본과 중국 등 열강의 각축장이 되어 국운은 풍전등화와 같았다.","data:image/jpeg;base64,","1",126.9998,37.57012]},"busan":{"해운대해수욕장":["126081","해운대해수욕장","해운대해수욕장은 넓은 백사장과 아름다운 해안선을 자랑하고 있으며 얕은 수심과 잔잔한 물결로 해수욕장의 최적 조건을 갖추고 있다.","data:image/jpeg;base64,","1",129.16028,35.15908],"광안리 (광안대교 야경)":["126078","광안리해수욕장","광안리해수욕장은 부산광역시 수영구에 위치한 해변으로, 맑고 푸른 바다와 고운 백사장이 어우러져 사계절 내내 많은 관광객이 찾는 명소이다.","data:image/jpeg;base64,","1",129.11898,35.15319],"자갈치시장":["132190","부산 자갈치시장","자갈치시장은 인근에 위치한 국제시장, 부평깡통시장과 함께 부산을 대표하는 전통시장이다.","data:image/jpeg;base64,","1",129.03058,35.09661]},"daegu":{"서문시장 (야시장)":["132532","대구 서문시장 & 서문시장 야시장","1920년대에 천황당지를 매립하여 지금의 장소로 이전한 대구 큰 장이라고 했던 서문시장은 오랜 역사를 가지고 있다.","","",128.58076,35.86888],"김광석다시그리기길":["1871383","김광석다시그리기길","김광석 길은 故 김광석이 살았던 대봉동 방천시장 인근 골목에 김광석의 삶과 음악을 테마로 조성한 벽화거리이다.","data:image/jpeg;base64,","1",128.60746,35.86142],"근대골목 (청라언덕)":["2042995","대구 근대골목(근대로의 여행)","근대문화골목은 2012년 한국 관광의 별로 선정되었으며, 한국관광 100선에 3년 연속 이름을 올리는 등, 골목투어를 전국적인 관광 콘텐츠로 이끈 가장 인기 있는 명소 중 하나이다.","","",128.58673,35.86774],"수성못":["1115613","수성못 유원지","수성유원지는 범물동 용지봉(629ｍ)에서 북서부로 뻗어 내린 줄기의 하부에 위치하여 주변의 완만한 산지와 수성못을 끼고 자연의 경관미를 이루고 있다.","data:image/jpeg;base64,","1",128.6177,35.8276]},"incheon":{"차이나타운 · 개항장 거리":["264512","인천 차이나타운","인천 차이나타운은 1883년 인천항이 개항되고 1884년 제물포 지역이 청나라의 치외법권 지역으로 지정되면서 형성된 곳이다.","","",126.6179,37.4756],"월미도":["127585","월미도","1989년 7월 문화의 거리가 조성된 이래 문화예술의 장, 만남과 교환의 장 그리고 공연놀이마당 등으로도 알려지기 시작한 월미도는 인천 하면 떠올릴 만큼 유명한 곳이다.","data:image/jpeg;base64,","1",126.6001,37.4722],"송도 센트럴파크":["2465107","송도 센트럴파크","송도 고층빌딩 숲 사이, 자연을 담은 공원인 송도 센트럴파크는 뉴욕 센트럴파크를 모티브로 만들어졌다.","data:image/jpeg;base64,","1",126.6383,37.3929],"소래포구":["2020690","소래포구","소래포구는 인천광역시에 위치해 있으며, 수도권에 가장 쉽게 바다를 느낄 수 있는 여행지 중 하나이다.","data:image/jpeg;base64,","1",126.74005,37.39885]},"gwangju":{"국립아시아문화전당":["2009775","국립아시아문화전당","국립아시아문화전당(ACC)은 아시아 과거-현재의 문화 예술과 혁신적인 아이디어, 신념이 만나 미래지향적인 새로운 결과물을 생산해 내는 국제적인 예술기관이자 문화 교류기관이다.. 5·18 민주화운동…","data:image/jpeg;base64,","1",126.91928,35.14605],"무등산 국립공원":["127575","무등산국립공원(광주)","무등산은 1972년 5월 22일 도립공원으로 지정되었으며, 2013년 3월 4일 국립공원 제21호로 지정되었다.","","3",126.94789,35.13147],"1913송정역시장":["2488192","1913송정역시장","1913년부터 전남광주통합특별시 송정역과 함께 명맥을 같이한 송정역 매일시장은 100년 역사를 간직한 유서 깊은 전통시장이다.","data:image/jpeg;base64,","1",126.79172,35.1353]},"daejeon":{"엑스포과학공원 · 한빛탑":["125994","대전엑스포과학공원","우리나라 최초의 국제박람회기구(BIE) 공인 전문 엑스포로 개최되었던 '93년 대전세계박람회를 기념하기 위해 그 시설과 부지를 국민 과학교육의 장으로 활용하기 위하여 조성된 과학공원이다.","","3",127.38025,36.37595],"대청호 오백리길":["1907688","대청호오백리길","대청호오백리길은 대전(동구, 대덕구)과 충북(청원, 옥천, 보은)에 걸쳐 있는 약 220㎞의 도보길이며 대청호 주변 자연부락과 소하천, 등산길, 임도, 옛길 등을 포함하고 있다.","data:image/jpeg;base64,","1",127.47194,36.37386],"장태산자연휴양림":["129438","장태산자연휴양림","장태산 자연휴양림은 국내 유일의 메타세쿼이아 숲이 울창하게 형성되어 있어 이국적인 경관과 더불어 가족 단위 산림욕을 즐기기에 적합한 곳이다.","data:image/jpeg;base64,","1",127.34126,36.21591],"유성온천":["125858","유성온천지구","유성온천지구는 대전 원도심에서 서쪽으로 약 11km가량 떨어진 유성구의 중심을 이루고 있는 대단위 온천관광타운이다.","","3",127.34479,36.3553]},"ulsan":{"태화강 국가정원":["128202","태화강 국가정원","태화강 국가정원은 1급수 생태하천 태화강을 끼고 있는 친환경 생태 정원으로 시간제한 없이 이용할 수 있는 도심 한가운데 위치한 울산 관광의 요지이다.","","3",129.2962,35.5478],"대왕암공원":["127515","대왕암공원","대왕암 공원은 우리나라에서 울주군 간절곶과 함께 해가 가장 빨리 뜨는 대왕암이 있는 곳이다.","data:image/jpeg;base64,","1",129.43525,35.49042],"간절곶":["128022","간절곶","울산 울주군에 위치한 간절곶은 한반도에서 해가 가장 먼저 떠오르는 곳으로, 매년 새해 첫날이면 해맞이를 보기 위해 수많은 이들이 찾는 대표적인 명소이다.","data:image/jpeg;base64,","1",129.36054,35.35893],"장생포 고래문화마을":["2381176","장생포 고래문화마을","2015년 조성된 고래문화마을에서는 예전 장생포 고래잡이 어촌의 모습을 그대로 재현하였으며, 고래광장, 장생포 옛 마을, 선사시대 고래마당, 고래조각 정원, 수생 식물원 등 다양한 테마와 이야기를…","data:image/jpeg;base64,","1",129.3831,35.50592]},"sejong":{"세종호수공원":["1946955","세종호수공원","세종호수공원은 세종시 중심에 위치한 호수로서 세종시 및 인근주민들에게 휴식 및 문화의 공간이다.","","3",127.27018,36.49895],"국립세종수목원":["2675068","국립세종수목원","국립세종수목원은 국내 최초의 도심형 국립수목원이다.","data:image/jpeg;base64,","1",127.28569,36.49861]},"suwon":{"수원화성 (유네스코 세계유산)":["4067984","수원화성 성곽길","수원화성 성곽길은 유네스코 세계문화유산으로 등록되어 있는 수원화성을 돌아보며 문화의 우수성을 알 수 있는 역사·사적길이다.","data:image/jpeg;base64,","1",127.01726,37.27735],"화성행궁":["129437","화성행궁","행궁은 정조가 현륭원에 행차할 때 임시 거처로 사용하던 곳으로 그 어느 행궁보다 크고 웅장하였으며 활용도도 높아 경복궁의 ‘부궁’이라는 말까지 생겨난 곳이다.","data:image/jpeg;base64,","1",127.01637,37.28182],"행리단길":["3033047","행리단길","행리단길은 서울 경리단길처럼 개성 넘치는 맛집과 카페가 몰려 있는 곳으로 화서공원에서 수원 화성 화홍문에 이르는 총 612m 거리를 이르는 말이다.","","",127.01276,37.28534],"통닭거리":["2613664","수원통닭거리","수원 팔달구 팔달로 100m 길이의 작은 골목에 있는 수원통닭거리는 1970년부터 문을 연 원조 가게부터 신생 가게까지 11곳 정도의 가게가 통닭을 튀겨내고 있는 곳이다.","","3",127.01764,37.27944]},"seongnam":{"율동공원":["128040","율동공원","성남 율동공원은 자연을 최대한 살려 조성한 자연호수공원으로, 잔디밭과 야산, 호수 등의 경치가 아름답다.","","3",127.15241,37.37656]},"uijeongbu":{"의정부 부대찌개거리":["612807","의정부 부대찌개거리","의정부 부대찌개거리는 옛 양주 군청 옆에 부대찌개 음식점들이 모여 형성된 음식특화 거리로 지정·운영되고 있는 관광테마골목 중의 하나이다.","","3",127.04913,37.74457]},"anyang":{"안양예술공원":["125514","안양예술공원","삼성산과 관악산 자락의 계곡을 따라 공공예술 작품과 산책로가 이어지는 주제공원이다.","data:image/jpeg;base64,","1",126.91957,37.41906]},"bucheon":{"한국만화박물관":["2470347","한국만화박물관","이곳은 국내 최초, 최대의 만화 전문 박물관으로 각종 희귀 자료와 원로작가들의 원화 등 만화에 관련된 모든 자료를 보존, 전시하고 있다.","data:image/jpeg;base64,","1",126.74219,37.5082]},"gwangmyeong":{"광명동굴":["2649975","광명동굴","1912년 일제가 자원수탈을 목적으로 개발을 시작한 광명동굴(구. 시흥광산)은 일제강점기 징용과 수탈의 현장이자 해방 후 근대화ㆍ산업화의 흔적을 고스란히 간직한 산업유산이다.","data:image/jpeg;base64,","1",126.86488,37.4243],"광명전통시장":["1754696","광명전통시장","1970년대 초 닷새마다 열리는 작은 오일장으로 시작하여 지금은 350여 개의 점포가 들어서 있는 경기지역 3대 재래시장으로 불릴 만큼 유명한 광명시 대표적 재래시장이다.","","3",126.85614,37.47988]},"pyeongtaek":{"평택호관광단지":["127562","평택호관광단지","평택호 관광단지는 평택호 주변의 아름다운 경관을 활용하여 다양한 볼거리, 문화공간, 편의시설이 조성된 평택의 대표 관광지다.","","",126.92223,36.92144]},"dongducheon":{"소요산":["127513","소요산국민관광지","소요산은 경기도 동두천시 동북방 소요동에 위치하고 동두천시청에서 3번 국도를 따라 북쪽으로 약 5㎞가량 지난 곳에 있는 수도권 최고의 단풍 명산이다.","data:image/jpeg;base64,","1",127.07057,37.94647]},"ansan":{"대부도":["126844","대부도","안산의 하와이로 불리는 대부도는 시화방조제로 연결이 되어 육지가 된 섬이지만 아직도 섬이 가진 낭만과 서정이 곳곳에 남아있는 곳이다.","","3",126.58526,37.24367]},"goyang":{"일산호수공원":["127197","일산호수공원","일산호수공원은 일산신도시 택지개발사업과 연계하여 조성한 근린공원이다.","data:image/jpeg;base64,","1",126.76386,37.65706],"행주산성":["125562","행주산성","행주산성은 경기도 고양시 덕양구 행주내동 덕양산의 7, 8부 능선에 쌓은 테뫼식[山頂式] 성으로 흙을 이용해서 쌓은 산성이다.","data:image/jpeg;base64,","1",126.82645,37.59607]},"gwacheon":{"서울대공원":["126712","서울대공원","서울대공원은 경기도 과천시에 위치한 종합 테마파크로, 1984년 개장 이후 자연과 문화, 여가를 함께 즐길 수 있는 복합 휴식 공간으로 사랑받고 있다.","data:image/jpeg;base64,","1",127.0139,37.43645],"서울랜드":["126719","서울랜드","한국 최초의 놀이공원이라는 타이틀을 가진 서울랜드는 개장과 동시에 대한민국 대표 테마파크로 자리매김했다.","","3",127.02382,37.43551],"국립과천과학관":["660722","국립과천과학관","국립과천과학관은 과학기술을 놀이처럼 즐길 수 있는 매력적인 과학문화 체험시설이다.","data:image/jpeg;base64,","1",127.00578,37.43812],"국립현대미술관 과천관":["129764","국립현대미술관 과천","국립현대미술관 과천관은 청계산의 자연경관과 어우러진 건축물과 넓은 야외조각공원을 갖추고 있으며, 옛 성곽과 봉화대, 전통마을의 담장과 계단 등 전통적인 요소를 현대적으로 표현한 건축 양식이 특징이…","data:image/jpeg;base64,","1",127.01997,37.43097]},"guri":{"동구릉 (유네스코 조선왕릉)":["125545","구리 동구릉 [유네스코 세계유산]","동구릉(東九陵)은 ‘동쪽에 있는 9기의 능’이라는 뜻으로, 약 450여 년간 7명의 왕과 10명의 왕비가 잠들어 있는 조선 최대의 왕릉군이다.","data:image/jpeg;base64,","1",127.13728,37.61652],"구리한강시민공원":["228874","구리한강시민공원(코스모스공원)","구리한강시민공원에 조성된 꽃단지는 시민들이 즐거운 시간을 함께 나눌 수 있는 곳이다.","data:image/jpeg;base64,","1",127.13286,37.57448]},"namyangju":{"수종사":["129516","수종사","수종사는 남양주 조안면 송촌리 운길산의 정상 부근에 있는 봉선사의 말사이다.","","3",127.30172,37.56873]},"osan":{"물향기수목원":["128986","물향기수목원","경기도 오산시에 위치한 물향기수목원은 도심 속 자연생태를 보전하고 다양한 식물자원을 전시·교육하는 공립수목원이다.","data:image/jpeg;base64,","1",127.0622,37.16737]},"siheung":{"오이도":["128109","오이도","오이도는 시흥시의 서남쪽 해변에 위치한 섬 아닌 섬으로서 각종 어패류가 많이 나는 관광지이자 신석기시대를 비롯한 각 시기의 유적이 여러 차례에 걸쳐 발굴되어 국가 사적으로 지정된 중요 유적지이다.","data:image/jpeg;base64,","1",126.68749,37.34554]},"gunpo":{"철쭉동산":["2751298","철쭉동산","군포의 철쭉동산은 수리산 등산로와 이어져 잇는 작은 언덕에 인공으로 조성한 철쭉 단지이다.","data:image/jpeg;base64,","1",126.9259,37.35428],"수리산":["125457","수리산도립공원","수리산은 군포시를 병풍처럼 둘러싸고 있는 군포시의 진산으로 2009년에 경기도의 세 번째 도립공원으로 지정되었다.","","3",126.90052,37.348]},"uiwang":{"철도박물관":["2463812","의왕철도박물관","1호선 의왕역 부근에 위치한 의왕철도박물관은 한국철도공사(코레일)에서 대규모 운송수단이자 국민의 생활수단인 철도의 역사와 문화를 널리 인식시키기 위하여 설립한 박물관이다.","data:image/jpeg;base64,","1",126.95003,37.31401]},"hanam":{"검단산":["750824","검단산","하남 시청 동쪽에 위치한 높이 657m로 하남시의 대표적인 명산으로 유명하다.","","",127.24938,37.51751]},"yongin":{"에버랜드":["127797","에버랜드","1년 365일 계절마다 다채롭게 펼쳐지는 축제와 어트랙션, 동물·식물 등 다양한 시설을 갖춘 에버랜드는 즐거운 휴식과 특별한 추억을 선사하는 테마파크이다.","","3",127.20213,37.29407],"한국민속촌":["125578","한국민속촌","한국민속촌은 오랜 시간을 거쳐 전승되어 온 우리 문화 속 생활풍속을 한데 모아 내외국인 관광객에게 우리의 전통문화를 소개하기 위해 1974년에 설립되었다.","data:image/jpeg;base64,","1",127.11458,37.25671]},"paju":{"헤이리 예술마을":["128168","헤이리 예술마을","헤이리 예술마을은 15만 평 규모로 통일동산 관광특구 내에 위치해 있다.","data:image/jpeg;base64,","1",126.6993,37.78801]},"icheon":{"이천도자예술마을 (예스파크)":["2763775","이천도자예술마을 (이천 예스파크)","경기도 이천시 신둔면에 위치한 이천도자예술마을은 공방마다 특색이 있어 구경삼아 둘러보다가 마음에 드는 것이 있으면 구매할 수 있으며, 걷다가 잠시 카페에 들러 휴식을 취할 수도 있다.","data:image/jpeg;base64,","1",127.38568,37.2931],"설봉공원":["1624755","설봉공원","경기도 이천시의 중심에 위치한 설봉공원은 수려한 자연경관 속에서 조각 예술과 도자 문화를 동시에 만끽할 수 있는 이천의 대표적인 힐링 명소이다.","data:image/jpeg;base64,","1",127.42787,37.27967]},"anseong":{"안성맞춤랜드 (남사당 공연)":["2525563","안성맞춤랜드","안성맞춤랜드는 2012년에 개장한 대규모 부지 내에 준공된 시민공원이다.","","",127.3102,37.03192],"안성팜랜드":["2463653","안성팜랜드","안성팜랜드는 가축들을 직접 만지고 먹이주며 즐거운 체험을 할 수 있는 체험목장이다.","","3",127.19441,36.99209],"미리내성지":["127556","미리내성지","경기도 안성에서 북쪽으로 40리쯤 떨어져 은하수라는 뜻의 아름다운 우리말로 불리고 있는 미리내성지는 한국 최초의 사제 김대건 신부의 묘소와 그의 어머니 우르술라, 김 신부에게 사제품을 준 조선 교…","data:image/jpeg;base64,","1",127.25914,37.14843]},"gimpo":{"애기봉 평화생태공원":["125454","애기봉평화생태공원","김포 최대의 평화관광지 애기봉평화생태공원은 한반도 유일 남·북 공동 이용수역(Free-zone)에 위치하여 평화와 화합을 대표하는 상징적인 장소이다.","data:image/jpeg;base64,","1",126.5946,37.75289],"대명항":["228863","김포 대명항","김포 대명항은 김포시의 어항으로 어판장에서 직접 해산물을 판매하는 김포의 지방어항이다.","data:image/jpeg;base64,","1",126.5417,37.63939],"김포 장릉":["126542","김포 장릉(원종·인헌왕후) [유네스코 세계유산]","장릉은 조선 16대 인조(1623~1649)의 생부인 원종과 그의 비 인헌왕후 구씨의 능이다.","data:image/jpeg;base64,","1",126.71557,37.61246]},"hwaseong":{"융릉 · 건릉 (유네스코 조선왕릉)":["127447","화성 융릉(장조·헌경황후)과 건릉(정조·효의황후) [유네스코 세계유산]","융릉은 황제로 추존된 장조와 헌경황후 홍씨의 능이다.","data:image/jpeg;base64,","1",126.98927,37.20813],"제부도":["125503","제부도","서신면 앞 바다에 있는 작은 섬, 제부도는 ‘모세의 기적’이 일어나는 신비의 섬이다.","data:image/jpeg;base64,","1",126.62447,37.16861],"전곡항":["2514428","전곡항","제부도와 누에섬과 마주하는 항구이다.","data:image/jpeg;base64,","1",126.6507,37.1876],"궁평항":["2514454","궁평항","낙조가 아름다운 곳으로 유명한 궁평항은 2008년 국가 어항으로 지정되었다.","data:image/jpeg;base64,","1",126.68127,37.11603]},"gwangju-gg":{"남한산성 (유네스코 세계유산)":["2751248","남한산성행궁","임금이 서울의 궁궐을 떠나 도성 밖으로 행차하는 경우 임시로 거처하는 곳을 행궁이라 한다.","","3",127.18151,37.47884],"화담숲":["2436233","화담숲","화담숲은 LG 상록재단이 공익사업의 일환으로 설립·운영하는 수목원이며, 2006년 4월 조성 승인을 받아 경기도 광주시 도척면 도웅리에 조성되었다.","data:image/jpeg;base64,","1",127.28942,37.34076]},"yangju":{"양주 회암사지":["126544","양주 회암사지","양주 회암사지는 천보산 남쪽에 자리한 고려 말·조선 초의 왕실 사찰 유적이다.","","3",127.1053,37.8453]},"pocheon":{"국립수목원 (광릉숲)":["127497","국립수목원","국립수목원은 광릉숲 보전 대책에 따라 1999년 5월 24일 독립 신설된 산림생물종 전문 연구기관이다.","data:image/jpeg;base64,","1",127.16892,37.75954],"허브아일랜드":["127695","허브아일랜드","관광농원인 허브아일랜드(329,000㎡) 내 식물원과 전시실(110,000㎡)을 갖춘 1종 전문 박물관(식물원)으로 등록한 전국 최대 규모의 허브 식물원이다.","","3",127.13347,37.96618]},"yeoju":{"신륵사":["128926","신륵사(여주)","신륵사는 봉미산 기슭에 위치한 여주의 대표적인 사찰이다.","data:image/jpeg;base64,","1",127.65968,37.2972]},"chuncheon":{"남이섬":["128019","남이섬","남이섬은 ‘동화 나라, 노래의 섬’을 콘셉트로 다양한 문화행사, 콘서트 및 전시를 꾸준히 개최해 오고 있으며, 어린이들에게는 꿈과 희망을, 연인들에게는 사랑과 추억을, 문화계 인사들에게는 창작의…","","3",127.52549,37.79627],"소양강 스카이워크":["2396037","소양강스카이워크","강 위로 시원하게 뻗은 소양강스카이워크는 전체 길이가 174m로, 바닥이 투명 강화유리로 된 구간만 무려 156m에 이른다.","data:image/jpeg;base64,","1",127.72366,37.89328],"김유정문학촌":["127933","김유정문학촌","김유정문학촌은 한국의 영원한 청년작가로 불리는 김유정 작가를 기리기 위해 김유정 생가터를 중심으로 조성한 문학촌이다.","data:image/jpeg;base64,","1",127.71768,37.81836],"레고랜드":["2815362","레고랜드 코리아 리조트","레고랜드 코리아 리조트(LEGOLAND® Korea Resort)는 강원 춘천시에 위치한 국내 최초의 글로벌 테마파크이자 전 세계 10번째로 설립된 레고랜드 리조트이다.","","",127.69846,37.88473]},"wonju":{"소금산 그랜드밸리 (출렁다리)":["2800692","소금산그랜드밸리","원주의 떠오르는 핫플레이스 소금산 그랜드밸리는 소금산 출렁다리를 포함한 간현관광지의 주간코스를 말한다.","data:image/jpeg;base64,","1",127.83507,37.36247],"뮤지엄 산":["2633832","뮤지엄산","산속에 감춰진 Museum SAN(Space, Art, Nature)은 노출 콘크리트의 미니멀한 건축물의 대가 ‘안도 타다오’의 설계로 공사를 시작하여 빛과 공간의 예술가 ‘제임스 터렐’의 작품을…","","",127.82341,37.41533]},"gangneung":{"경포대 · 경포해변":["125790","강릉 경포대","강릉 경포대는 강릉을 대표하는 명승지 중 하나로, 국가지정문화유산인 보물로 지정되어 있다.","data:image/jpeg;base64,","1",128.89648,37.79551],"안목해변 커피거리":["127722","안목해변","강릉을 대표하는 해변 중 하나인 안목해변은 푸른 동해 바다와 향긋한 커피 향이 어우러진 특별한 명소이다.","data:image/jpeg;base64,","1",128.94828,37.77226],"정동진":["3545967","정동진","‘정동진’은 강원도 강릉시 강동면 정동진리에 위치하고 있는 바닷가로 한양의 광화문에서 정동쪽에 있는 나루터가 있는 마을이라는 뜻으로 이름 지어졌다.","","",129.03257,37.69136]},"donghae":{"무릉계곡":["125677","무릉계곡","동해시 두타산과 청옥산을 배경으로 약 4㎞에 달하는 계곡이다.","data:image/jpeg;base64,","1",129.01932,37.46312],"추암 촛대바위":["129000","추암 촛대바위","동해시의 명소 추암 촛대바위는 수중의 기암괴석이 바다를 배경으로 함께 어울려 빚어내는 비경으로 감탄을 자아내는 장소다.","data:image/jpeg;base64,","1",129.1601,37.4794],"묵호등대 · 논골담길":["129176","묵호등대","묵호등대는 항해하는 선박들의 안전운항에 기여하기 위해 묵호항 근처에 1963년 6월 8일 건립되었다.","","3",129.11847,37.55483]},"taebaek":{"태백산 국립공원":["125590","태백산 국립공원","태백산은 백두대간의 중앙부에 솟아 있는 민족의 영산이며, 한강과 낙동강, 삼척의 오십천이 발원하는 한반도 이남의 젖줄이 되는 뿌리산이다.","","3",128.98825,37.14932],"황지연못 (낙동강 발원지)":["125740","황지연못","낙동강의 발원지로 시내 중심부에 위치하며 이 못에서 솟아나는 물이 드넓은 영남평야를 도도히 흘러가게 된다.","data:image/jpeg;base64,","1",128.99102,37.17271],"검룡소 (한강 발원지)":["126840","검룡소","검룡소는 용신이 사는 못이라 하여 붙여진 이름으로 한강은 이곳에서 발원되어 서해로 흘러간다.","","3",128.92429,37.22747],"바람의 언덕 (매봉산)":["2610091","매봉산 바람의 언덕","태백에 위치한 매봉산 바람의 언덕은 바람이 많이 불고 언덕 위에 풍력발전기가 있어 이 같은 별명이 붙은 것으로 알려졌다.","data:image/jpeg;base64,","1",128.9648,37.2148]},"sokcho":{"설악산 국립공원":["127586","설악산 국립공원(외설악)","설악산 국립공원은 강원특별자치도 속초시를 중심으로 고성군·인제군·양양군에 걸쳐 있는 우리나라 대표 산악형 국립공원이다.","data:image/jpeg;base64,","1",128.5168,38.16752],"속초관광수산시장":["1260275","속초관광수산시장","속초 여행의 필수 코스로 꼽히는 속초관광수산시장은 동해안의 싱싱한 수산물과 특산물로 넘쳐나는 곳이다.","data:image/jpeg;base64,","1",128.59052,38.20394],"아바이마을":["251738","아바이마을","속초시 청호동에 위치한 실향민 집단촌으로, 속칭 아바이촌, 함경도 아바이집단촌이라고도 한다.","data:image/jpeg;base64,","1",128.59489,38.20068],"영금정":["125779","영금정","속초시 동명동 속초등대 밑의 바닷가에 크고 넓은 바위들이 깔려있는 곳이 영금정이다.","data:image/jpeg;base64,","1",128.60144,38.21185]},"samcheok":{"환선굴":["126729","환선굴","환선굴은 1662년 허목 선생이 저술한 『척주지』에 처음 기록된 우리나라 최대 규모의 석회암 동굴이다.","","3",129.02122,37.32636],"장호항":["125711","장호해변·장호항","장호해변은 삼척에서 남쪽으로 25km 정도의 거리에 위치하며, 용화해변과 함께 아름다운 백사장을 자랑하고 있다.","data:image/jpeg;base64,","1",129.3142,37.2859],"삼척해상케이블카":["2513410","삼척해상케이블카","동해안에서 아름답기로 소문난 용화-장호해변을 한눈에 내려다볼 수 있는 케이블카이다.","data:image/jpeg;base64,","1",129.30852,37.28914]},"pyeongchang":{"대관령 양떼목장":["129263","대관령양떼목장","한국 농림부에서 지정한 동물복지와 산림보존에 특화된 목장이다.","","",128.7533,37.68759]},"cheongju":{"청남대":["127916","청남대","청남대는 대청호반에 자리 잡고 있는 청남대는 따뜻한 남쪽의 청와대라는 뜻으로 1983년부터 대한민국 대통령의 공식 별장으로 이용되던 곳이다.","data:image/jpeg;base64,","1",127.4918,36.4628],"국립현대미술관 청주":["2598367","국립현대미술관 청주","국립현대미술관은 1969년 경복궁에서 개관한 이래로 2018년에는 충청북도 청주시 옛 연초제조창을 재건축한 국립현대미술관 청주를 개관하여 중부권 미술문화의 명소로 육성하고자 노력하고 있으며, 20…","data:image/jpeg;base64,","1",127.49022,36.65553]},"chungju":{"충주호":["125872","충주호","충주댐 건설로 생긴 충주호는 내륙의 바다라 불릴 정도로 규모가 크다.","data:image/jpeg;base64,","1",128.04,36.9581],"탄금대":["125870","충주 탄금대","충주 탄금대는 우리나라 3대 악성 중 하나인 우륵이 가야금을 연주하던 곳이라 하여 탄금대란 명칭이 붙은 곳이며 임진왜란 때 신립장군이 소서행장과 맞서 싸우다 패전하자 투신한 곳으로 역사적 가치가…","data:image/jpeg;base64,","1",127.89829,36.98825]},"jecheon":{"청풍호반케이블카":["2606296","청풍호반케이블카","청풍호반케이블카는 제천의 명소, 청풍호반의 아름다운 경치를 감상할 수 있는 곳으로 청풍면 물태리에서 비봉산 정상까지 2.3km 구간을 왕복 운행한다.","data:image/jpeg;base64,","1",128.16678,37.00126],"배론성지":["125982","배론성지","배론성지는 충청북도 제천시 봉양읍에 위치한 조선 후기 천주교 성지이다.","data:image/jpeg;base64,","1",128.08377,37.16116]},"cheonan":{"독립기념관":["129790","독립기념관","독립기념관은 항일투쟁의 역사를 제대로 정립하고, 이를 널리 알리려는 목적으로 건립되었다.","data:image/jpeg;base64,","1",127.2304,36.78187],"각원사":["125885","각원사","충청남도 천안시에 위치한 각원사는 남북통일을 기원하기 위해 불교신도들과 많은 사람들의 정성 어린 성금들에 의해 1975년 창건된 사찰이다.","data:image/jpeg;base64,","1",127.197,36.8337]},"gongju":{"무령왕릉 (송산리 고분군)":["126681","공주 무령왕릉과 왕릉원[유네스코 세계유산]","사적 공주 무령왕릉과 왕릉원은 백제 웅진시기(475~538년) 왕들의 무덤이 모여있는 곳이다.","data:image/jpeg;base64,","1",127.11439,36.46304]},"boryeong":{"대천해수욕장":["127866","대천해수욕장","충남 보령시 해수욕장 4길 일원은 대천해수욕장이다.","data:image/jpeg;base64,","1",126.5136,36.3103],"죽도 상화원":["128069","죽도 (보령)","죽도(보령)는 보령시 남서부 남포방조제 중간에 위치한 관광지이다.","","3",126.53855,36.27727]},"asan":{"현충사":["125945","현충사","현충사는 임진왜란에서 나라를 구한 영웅 충무공 이순신장군의 사당으로 1706년(숙종 32)에 처음 세워졌다.","data:image/jpeg;base64,","1",127.0312,36.80655],"외암민속마을":["126001","외암민속마을","국가민속문화유산로 지정된 마을이다.","data:image/jpeg;base64,","1",127.01443,36.73099],"온양온천":["125856","온양온천지구","온양온천은 충청남도 아산시 온천동 일대에 있는 온천 지역으로, 오래된 역사와 전통을 지니고 있다.","data:image/jpeg;base64,","1",126.99951,36.78328],"지중해마을":["2606741","지중해마을","지중해마을은 이국적인 유럽풍 건물이 모여 지중해의 작은 시골 마을을 연상시키는 곳이다.","data:image/jpeg;base64,","1",127.06162,36.79694]},"seosan":{"해미읍성":["125990","서산 해미읍성","서산 해미읍성은 1491년 조선 성종 때 축조된 대표적인 평지 읍성으로 둘레 약 1.8㎞의 석성과 동문·남문·서문이 잘 보존된 역사 유적이다.","data:image/jpeg;base64,","1",126.5486,36.7121],"서산 용현리 마애여래삼존상":["125991","서산 용현리 마애여래삼존상","서산마애삼존불이라고도 불리는 이것은 백제 후기인 7세기경에 바위에 불상을 새긴 것으로 백제의 미소가 어떤 것인지를 느낄 수 있는 문화유산이자 예술 작품이다.","data:image/jpeg;base64,","1",126.60522,36.77344],"간월암":["125880","간월암(서산)","간월암은 부석면 간월도리에 위치한 작은 암자로 조선 초 무학대사가 창건하였으며 송만공 대사가 중건하였다고 전해진다.","","3",126.41141,36.60379]},"nonsan":{"관촉사 (은진미륵)":["125905","관촉사(논산)","관촉사(논산)은 논산 시내 남부 반야산 동쪽 자락에 자리한 사찰로 논산 8경 중에서도 제1경으로 꼽히는 명승지다.","data:image/jpeg;base64,","1",127.11367,36.18879],"탑정호 출렁다리":["2714510","논산 탑정호 출렁다리","탑정호 출렁다리는 탑정호 출렁다리는 충청남도 논산시 휴양관광산업의 랜드마크로 특별한 볼거리를 선사하는 호수 위에 설치된 가장 긴 출렁다리로 KRI 한국기록원에 인정받았다.","data:image/jpeg;base64,","1",127.1589,36.1817],"선샤인랜드":["2606192","선샤인랜드","충남 논산에 위치한 선샤인랜드는 다양한 체험과 관람을 즐길 수 있는 복합문화공간으로, 밀리터리 체험관, 선샤인스튜디오, 1950스튜디오로 구성되어 있다.","data:image/jpeg;base64,","1",127.106,36.10195]},"dangjin":{"솔뫼성지":["125969","솔뫼성지","솔뫼는 충청도에서 제일 좋은 땅 ‘내포’ 한가운데 자리하고 있으며, ‘소나무가 우거진 작은 동산’이라는 뜻을 가지고 있다.","data:image/jpeg;base64,","1",126.78652,36.81953],"왜목마을":["129064","왜목마을","왜목마을은 당진시 최북단에 위치한 서해안의 마을이다.","data:image/jpeg;base64,","1",126.52422,37.04463],"아미미술관":["2704339","아미미술관","아미미술관은 폐교된 (구) 유동초등학교를 활용해 만든 사립미술관으로, 전통문화유산과 자연환경이 급속도로 파괴되고 사라져 가는 현 상황에서 지역의 건축, 문화, 풍속, 생활상 등을 훼손하지 않고 원…","data:image/jpeg;base64,","1",126.68032,36.86214]},"jeonju":{"경기전":["147656","전주 경기전","태조 이성계의 어진을 봉안하고 제사하는 전각인 전주 경기전은 1991년 1월 9일 사적으로 지정되었다.","data:image/jpeg;base64,","1",127.15002,35.81417],"전동성당":["250331","전주전동성당","전주 전동성당은 사적으로 조선시대 천주교도의 순교 터에 세워졌다.","data:image/jpeg;base64,","1",127.14928,35.81382],"남부시장 야시장":["132326","전주 남부시장","남부시장의 역사는 조선 초기로 거슬러 올라간다.","","3",127.14754,35.81278]},"gunsan":{"경암동 철길마을":["2605528","경암동 철길마을","경암동 철길마을은 1944년 전라북도 군산시 경암동에 준공하여 페이퍼 코리아 공장과 군산역을 연결하는 총연장 2.5km 철로 주변의 마을을 총괄하여 붙인 이름이다.","","3",126.73622,35.98131],"선유도 (고군산군도)":["226923","선유도","본래 군산도라 불렸으나 섬의 북단 해발 100여 미터의 봉 정상의 형태가 마치 두 신선이 마주 앉아 바둑을 두고 있는 것처럼 보인다 하여 선유도라 불리게 되었다.","","3",126.41239,35.81016],"초원사진관":["2605927","초원사진관","초원사진관은 1998년 1월에 개봉한 영화 의 촬영 장소로 유명한 곳이다.","","3",126.70837,35.98769]},"iksan":{"왕궁리 유적":["250462","익산 왕궁리유적 [유네스코 세계유산]","전북특별자치도 익산시 왕궁면에 위치한 왕궁리유적은 백제 30대 무왕(600 ~ 641)대에 조성되어 그 후 사찰로 변화했다.","data:image/jpeg;base64,","1",127.05572,35.97159]},"jeongeup":{"내장산 국립공원":["126237","내장산국립공원","내장산은 산 안에 숨겨진 것이 무궁무진하다 하여 붙여진 이름이다.","","3",126.86703,35.47105]},"namwon":{"광한루원":["126397","광한루원","광한루원은 전라북도 남원시에 있는 조선 전기에 조성된 광한루의 정원이다.","data:image/jpeg;base64,","1",127.37945,35.40332]},"gimje":{"벽골제":["130253","벽골제농경문화박물관","벽골제는 김제시 포교리와 월승리 일대의 저수지를 이르며 약 2.6㎞의 제방이 있으며, 우리나라에서 가장 오래되고 규모가 큰 저수지로 알려져 있다.","","3",126.8531,35.75462],"금산사":["126339","금산사(김제)","금산사는 백제시대에 창건되어 1400여 년의 역사를 이어 오늘날까지 법등을 밝혀온 유서 깊은 명찰이다.","data:image/jpeg;base64,","1",127.05345,35.7227]},"mokpo":{"유달산":["126257","유달산","목포의 유달산은 그리 높지는 않지만 노령산맥의 맨 마지막 봉우리이자 다도해로 이어지는 서남단의 땅끝인 산이다.","data:image/jpeg;base64,","1",126.37247,34.79034],"갓바위":["126828","갓바위 문화타운","목포 문화를 한 눈에 만날 수 있는 곳, 갓바위 문화타운은 목포 문화 예술의 집적지인 갓바위 문화타운은 목포의 예술과 역사를 보고 듣고 체험할 수 있는 문화의 공간이자, 밤에는 화려한 야경이 일품…","data:image/jpeg;base64,","1",126.42107,34.79373]},"yeosu":{"향일암":["127715","향일암(여수)","여수 향일암은 대한불교조계종 제19교구 말사이며, 연간 100만여 명이 찾는 관광명소이자 관음기도 도량이다.","data:image/jpeg;base64,","1",127.80364,34.59163],"이순신광장":["2612869","이순신광장","여수시 중앙동에 있는 이순신광장은 임진왜란을 승리로 이끈 이순신 장군에 대한 자료와 당시 의병에 대한 소개 등 역사적인 현장을 보고 느낄 수 있는 많은 볼거리가 있는 곳이다.","","3",127.73571,34.73986]},"suncheon":{"순천만습지":["126730","순천만습지","순천만은 우리나라 남해안 중서부에 위치한 만으로서, 전남광주통합특별시 순천시와 고흥군, 여수시로 둘러싸여 있다.","data:image/jpeg;base64,","1",127.50928,34.8858],"순천만국가정원":["1919548","순천만국가정원","순천만국가정원은 대한민국 제1호 국가정원이다.","","",127.4997,34.9286]},"naju":{"영산포 홍어거리":["1185331","영산포 홍어거리","영산포 홍어거리는 전라남도 나주시 영산포 일대에 조성된 음식거리로, 나주의 대표 향토음식인 삭힌 홍어를 맛볼 수 있는 명소이다.","","3",126.71038,34.99993]},"gwangyang":{"광양 매화마을":["126669","광양 매화마을","광양 매화마을은 섬진강 하류 백운산 자락에 자리한 곳으로, 매년 3월이면 새하얀 매화로 눈부신 곳이다.","data:image/jpeg;base64,","1",127.72052,35.07858]},"goheung":{"나로우주센터 우주과학관":["751881","나로우주센터 우주과학관","나로우주센터 우주과학관은 전남광주통합특별시 고흥군 외나로도에 위치한 우주과학 체험·교육 시설이다.","data:image/jpeg;base64,","1",127.51778,34.45352],"소록도":["126285","소록도","소록도는 전남광주통합특별시 고흥반도의 끝자락인 녹동항에서 1㎞가 채 안되는 곳에 위치하고 있으며, 섬의 모양이 어린 사슴과 비슷하다고 하여 소록도라고 불리운다.","data:image/jpeg;base64,","1",127.11386,34.51032]},"pohang":{"호미곶 (상생의 손)":["129168","호미곶 등대","육당 최남선 선생께서 호미곶 해 뜨는 광경은 「조선십경」의 하나라고 극찬할 정도로 아름다운 전경을 가진 곳에 바로 호미곶등대가 위치하고 있다.","","3",129.5694,36.07727],"영일대해수욕장":["127698","영일대해수욕장","영일대해수욕장은 경상북도 포항시 북구에 위치한 동해안 최대 규모의 해수욕장이다.","data:image/jpeg;base64,","1",129.3779,36.055],"스페이스워크":["2784715","환호공원 스페이스워크","포항 환호공원 내에 위치한 스페이스워크는 트랙길이 333m, 계단 개수 717개 규모로 만들어졌다.","data:image/jpeg;base64,","1",129.3903,36.0652]},"gyeongju":{"불국사 · 석굴암 (유네스코 세계유산)":["126166","경주 불국사 [유네스코 세계유산]","불국사는 신라 법흥왕 15년에 어머니의 뜻에 따라 국가의 안녕과 백성의 평안을 기원하며 창건되었다.","data:image/jpeg;base64,","1",129.33173,35.7923],"대릉원":["126214","천마총(대릉원)","경주 대릉원 안에 위치한 천마총은 5세기 말에서 6세기 초에 축조된 것으로 추정되는 통일 이전 신라의 고분이다.","data:image/jpeg;base64,","1",129.21047,35.83864],"동궁과 월지 (야경)":["128526","경주 동궁과 월지","경주 동궁과 월지는 신라 왕궁의 별궁 터이다.","data:image/jpeg;base64,","1",129.22834,35.83516]},"gimcheon":{"직지사":["126155","직지사","황악산 기슭에 있는 직지사는 대한불교 조계종 제8교구 본사이다.","data:image/jpeg;base64,","1",128.00282,36.11511],"부항댐 출렁다리":["2706622","부항댐 출렁다리","김천 부항댐 인근에는 물문화관, 인공습지, 수력발전소 등 환경친화적이고 문화생활 또한 즐길 수 있는 시설들이 조성되어 있다.","","",127.99693,35.98077]},"andong":{"도산서원":["126200","도산서원 [유네스코 세계유산]","도산서원은 건축물 구성상 크게 도산서당과 이를 아우르는 도산서원으로 구분된다.","data:image/jpeg;base64,","1",128.84035,36.72789],"병산서원":["126227","병산서원 [유네스코 세계유산]","병산서원은 고려 중기부터 안동 풍산에 있던 교육기관인 풍악서당(豐岳書堂)에서 비롯되었다.","data:image/jpeg;base64,","1",128.55281,36.54026],"월영교":["988449","월영교","월영교란 명칭은 댐 건설로 수몰된 월영대가 이곳으로 오게 된 인연과 월곡면, 음달골의 지명을 참고하여 지어지게 되었다.","data:image/jpeg;base64,","1",128.7609,36.5767]},"gumi":{"금오산 도립공원":["126016","금오산도립공원","금오산은 소백산맥의 지맥에 솟은 산으로 1970년 도립공원으로 지정되어 관광시설이 갖추어졌으며, 산 전체가 바위로 이루어져 기암절벽에 급경사가 많고, 산 아래에서 폭포까지는 케이블카가 설치되어 있…","data:image/jpeg;base64,","1",128.30531,36.10597],"구미에코랜드":["2500326","구미에코랜드","구미에코랜드는 경상북도 구미시 산동면 인덕리 일대에 조성된 종합 산림문화휴양시설로, 구미시산림문화관, 생태탐방 모노레일, 산동참생태숲, 자생식물단지, 산림복합체험단지, 어린이테마교과숲, 문수산림욕…","data:image/jpeg;base64,","1",128.46246,36.17711]},"yeongju":{"부석사 (유네스코 산사)":["127669","부석사 [유네스코 세계유산]","부석사는 신라 문무왕 16년(676) 해동 화엄종의 종조인 의상대사가 왕명으로 창건한 화엄종의 수사찰이다.","data:image/jpeg;base64,","1",128.6871,36.9984],"소수서원 (유네스코 서원)":["126201","영주 소수서원","1542년(중종 37년)에 풍기군수 주세붕(周世鵬)이 안향(安珦)을 기리기 위해 사당을 세운 것이 시초이다.","data:image/jpeg;base64,","1",128.57907,36.92525],"무섬마을":["894087","무섬마을","무섬마을은 물 위에 떠 있는 섬을 뜻하는 ‘물수리’의 우리말 이름을 가진 전통마을이다.","data:image/jpeg;base64,","1",128.6216,36.7319]},"yeongcheon":{"보현산 천문대":["127293","보현산 천문대","1996년 4월에 준공된 보현산 천문대는 국내 광학 천문 관측의 중심지이며, 항성, 성단, 성운, 은하, 폭발성 천체 등의 생성과 진화를 연구하고 있다.","","3",128.97601,36.1636],"은해사":["128155","은해사(영천)","영천시 청통면 팔공산 기슭에 있는 은해사는 대한불교조계종 제10교구 본사이다.","data:image/jpeg;base64,","1",128.79396,35.99025]},"sangju":{"경천섬":["2756567","경천섬(경천섬공원)","경천섬은 낙동강 상류에 위치한 약 20만㎡의 섬으로 그 섬을 둘러싸고 있는 생태공원을 경천섬 공원이라 부른다.","data:image/jpeg;base64,","1",128.25506,36.45323]},"mungyeong":{"문경새재 도립공원":["126017","문경새재도립공원","백두대간 조령산 마루를 넘는 문경새재는 예로부터 한강과 낙동강유역을 잇는 영남대로상의 가장 높고 험한 고개로 사회 문화 경제의 유통과 국방상의 요충지였다.","data:image/jpeg;base64,","1",128.07699,36.7616]},"gyeongsan":{"갓바위 (팔공산 관봉)":["126019","팔공산국립공원(갓바위지구)","팔공산은 대구광역시 동구, 군위군, 경상북도 경산시, 영천시, 칠곡군에 걸쳐있는 해발 1,192m의 산이다.","data:image/jpeg;base64,","1",128.73579,35.98222],"반곡지":["2704119","반곡지","경산시에 위치한 반곡지는 1903년에 만든 농업용 저수지이다.","data:image/jpeg;base64,","1",128.80664,35.78047]},"changwon":{"마산어시장":["1622326","마산어시장","마산어시장은 200여 개의 횟집과 수족관이 있으며 고급어종에서 부터 서민 밥상의 주인공인 고등어, 명태까지 무공해 청정해역인 남해안에서 갓 잡은 모든 선어를 한자리에서 만날 수 있는 곳이다.","data:image/jpeg;base64,","1",128.57896,35.20376],"창동예술촌":["1905110","창동예술촌","창동예술촌은 옛 마산 원도심권의 잃어버린 상권 기능을 재생시키기 위한 도시재생사업으로 50년대, 60년대 문화예술의 중심지였던 마산의 추억과 향수를 느낄 수 있는 문신예술골목, 마산예술흔적 골목,…","data:image/jpeg;base64,","1",128.57478,35.20707]},"jinju":{"진주성 · 촉석루":["126833","진주성","삼국 시대 거열성, 고려 시대 촉석성으로 불렀던 성곽으로 조선 시대에 이르러 진주성으로 개칭되었다.","data:image/jpeg;base64,","1",128.08025,35.18971]},"tongyeong":{"동피랑 벽화마을":["753306","동피랑마을","‘동피랑’이라는 이름은 ‘동쪽’과 ‘비랑’이라는 말이 합쳐져서 생겼다.","data:image/jpeg;base64,","1",128.42762,34.84531],"통영케이블카 (미륵산)":["533874","통영케이블카","통영 미륵산에 설치된 통영케이블카는 2선(bi-cable) 자동순환식 곤돌라 방식으로 스위스의 최신 기술에 의해 설치되었으며, 길이는 1975m이다.","data:image/jpeg;base64,","1",128.42508,34.8266],"한산도 제승당":["127105","한산도","통영시 남동쪽에 있는 섬으로 통영항에서 뱃길로 2㎞ 정도 떨어져 있는 한산도는 동쪽에는 비산도, 송도, 좌도가 있고, 남쪽에는 추봉도가 있는 한산면의 본섬으로, 면을 이루는 29개 유무인도 가운데…","data:image/jpeg;base64,","1",128.4868,34.7783],"디피랑":["2679716","디피랑(DPIRANG)","디피랑은 통영의 유명 벽화마을인 동피랑과 서피랑을 모티브로 이곳에서 사라진 벽화들이 다시 살아 움직인다는 이야기를 담은 미디어쇼를 선보이고 있다.","data:image/jpeg;base64,","1",128.42848,34.84206]},"sacheon":{"삼천포항":["2514747","삼천포항","삼천포항은 사천시에 있는 항구로 1966년 무역항으로 지정된 이후 남해안과 서해안을 유기적으로 연결하는 관문으로써 수출 광석류, 고령토 등을 처리하는 동시에 화력발전소 연료 수송지원항으로 발전하고…","data:image/jpeg;base64,","1",128.06966,34.92652],"실안 낙조":["2782734","실안낙조","사천팔경 중 제2경인 실안낙조는 전국 9대 일몰지의 하나로, 해 질 녘 부채꼴 모양의 참나무 말뚝으로 만든 죽방렴과 섬, 바다, 그리고 일몰이 환상적인 조화를 이룬다.","data:image/jpeg;base64,","1",128.0421,34.9395]},"gimhae":{"수로왕릉":["126192","김해수로왕릉","김해수로왕릉은 김해시 서상동에 있는 금관가야의 시조 수로왕의 무덤으로 사적으로 지정됐다.","data:image/jpeg;base64,","1",128.8784,35.2353],"국립김해박물관":["130690","국립김해박물관","국립김해박물관은 고고학 중심의 전문 박물관으로 특성화되어 있다.","data:image/jpeg;base64,","1",128.87343,35.24298],"가야테마파크":["2414696","김해가야테마파크","김해가야테마파크는 김해시민에게 편안한 휴식을 제공하는 일상 휴식 공간이며 가족·연인·친구와 함께 다양한 문화를 접할 수 있는 복합문화공간이다.","data:image/jpeg;base64,","1",128.89201,35.25219]},"miryang":{"위양지":["2545984","위양지(위양지 이팝나무)","신라시대 때 농업용수 공급을 위해 축조된 저수지로 백성들을 위한다는 의미에서 위양지라고도 한다.","data:image/jpeg;base64,","1",128.71677,35.54657]},"geoje":{"바람의 언덕":["129479","바람의 언덕","해금강 가는 길 왼쪽으로 내려가면 도장포 마을이 나오고, 그 마을 북쪽에 자리 잡은 곳이 바로 바람의 언덕이다.","data:image/jpeg;base64,","1",128.66331,34.74405],"외도 보타니아":["126581","외도 보타니아","외도 보타니아는 botani(식물)와 utopia(낙원)의 합성어로 식물의 천국이라는 뜻의 해상 식물 공원이다.","data:image/jpeg;base64,","1",128.71139,34.76947]},"yangsan":{"통도사 (유네스코 산사)":["126186","통도사(양산)","우리나라 3대 사찰의 하나인 통도사는 부처의 진신사리가 모셔져 있는 불보사찰이다.","","3",129.06472,35.48825],"배내골":["127655","배내골","영남알프스라고 하는 가지산 고봉들이 감싸고 있으며 산자락을 타고 흘러내리는 맑은 계곡물이 모여 한 폭의 그림을 연상하게 하는 곳이다.","data:image/jpeg;base64,","1",128.96466,35.45001]},"namhae":{"독일마을":["129489","남해독일마을","남해 독일마을은 1960~70년대 독일로 파견되었던 광부와 간호사들이 귀국 후 정착하며 형성된 독특한 테마 마을이다.","","3",128.03834,34.80005],"다랭이마을":["127778","다랭이마을","다랭이마을은 선조들이 농토를 한 뼘이라도 더 넓히려고 산비탈을 깎아 곧추 석출을 쌓고 계단식 다랭이 논을 만들었다고 한다.","","3",127.89096,34.72807],"보리암 (금산)":["126149","금산 보리암(남해)","683년 원효대사가 이곳에서 초당을 짓고 수도하면서 관세음보살을 친견한 뒤로 산 이름을 보광산, 초당 이름을 보광사라고 했다.","data:image/jpeg;base64,","1",127.98274,34.75185],"상주은모래비치":["126084","상주은모래비치","금산의 절경을 긴 병풍으로 삼은 상주은모래비치는 은빛 고운 모래로 이루어진 넓은 백사장과 울창한 송림으로 둘러싸여 전국에서 몇 안 되는 아름다운 자연경관을 간직한 해수욕장이다.","data:image/jpeg;base64,","1",127.98809,34.72084]},"jeju":{"한라산 (성판악·관음사 코스)":["127635","한라산","한라산은 능히 은하수를 잡아당길 만큼 높은 산이라는 뜻을 가졌다.","data:image/jpeg;base64,","1",126.53,33.3618],"협재해수욕장":["127490","협재해수욕장","협재해수욕장은 제주시 서쪽의 한림공원에 인접해 있다.","data:image/jpeg;base64,","1",126.23943,33.39375],"용두암":["228853","용두암","제주공항 인근의 북쪽 바닷가에 있는 용두암은 오랜 세월에 걸쳐 파도와 바람에 씻겨 빚어진 모양이 용의 머리와 닮았다 하여 용두암이라 불린다.","data:image/jpeg;base64,","1",126.5125,33.51475]},"seogwipo":{"성산일출봉 (유네스코 세계유산)":["126435","성산일출봉 [유네스코 세계자연유산]","해발 180m인 성산 일출봉은 약 5,000년 전 제주도 수많은 분화구 중에서는 드물게 바닷속에서 수중폭발한 화산체이다.","data:image/jpeg;base64,","1",126.9415,33.45808],"천지연폭포":["126438","천지연폭포","이름만큼이나 빼어난 서귀포 천지연폭포는 조면질 안산암의 기암절벽이 하늘높이 치솟아 마치 신선의 세계로 들어온 것 같은 황홀경을 느끼게 한다.","data:image/jpeg;base64,","1",126.55955,33.24472],"중문관광단지":["127492","중문관광단지","중문관광단지는 제주의 독특한 자연경관과 지리적 조건을 활용하여 제주특별자치도 서귀포시 중문, 대포, 색달동 일원에 조성한 국제적인 관광 휴양지이다.","","3",126.4125,33.2487],"쇠소깍":["129617","쇠소깍","제주도 서귀포시 하효동에 있는 쇠소깍은 원래는 소가 누워있는 형태라 하여 쇠둔이라는 지명이었는데 효돈천을 흐르는 담수와 해수가 만나 깊은 웅덩이를 만들고 있어 쇠소깍이라고 붙여졌다.","data:image/jpeg;base64,","1",126.6227,33.253]},"ulleung":{"나리분지":["128771","나리분지","나리분지는 신생대 제3기 말의 화산활동으로 인하여 점성이 강한 조면암, 안산암, 그리고 응회암이 분출되면서 칼데라 화구가 함몰하여 형성된 화구원이다.","","3",130.8676,37.5207],"봉래폭포":["126071","봉래폭포 (울릉도, 독도 국가지질공원)","봉래폭포는 총 3단으로 구성되어 있다.","data:image/jpeg;base64,","1",130.88334,37.49845],"내수전 일출전망대":["2616076","내수전일출전망대","울릉도 동쪽 끝 내수전 고개에 위치한 내수전일출전망대는 해발 440m의 높이에 위치해 있다.","data:image/jpeg;base64,","1",130.9097,37.5122],"관음도":["2616077","관음도 (울릉도, 독도 국가지질공원)","관음도는 죽도, 독도에 이어 세 번째로 큰 울릉도 부속섬이다.","data:image/jpeg;base64,","1",130.9207,37.5429]}};
